LinearStudy.powerSeriesQuotient_diagonal_jacobian.{u_1} {K : Type u_1} [Field K] {n : ℕ}
  (H : Fin (n + 1) → MvPowerSeries (Fin (n + 1)) K) (hzero : ∀ (i : Fin (n + 1)), MvPowerSeries.constantCoeff (H i) = 0)
  [IsArtinianRing (MvPowerSeries (Fin (n + 1)) K ⧸ Ideal.span (Set.range H))] :
  let Q := MvPowerSeries (Fin (n + 1)) K ⧸ Ideal.span (Set.range H);
  have q := Ideal.Quotient.mk (Ideal.span (Set.range H));
  ∃ M,
    LinearStudy.Annihilates (KaehlerDifferential.ideal K Q) M.det ∧
      (Algebra.TensorProduct.lmul' K) M.det = Matrix.det fun i j => q ((MvPowerSeries.pderiv j) (H i))

LinearStudy.coefficientDeterminant_annihilates_quotient.{u_1, u_2} {R : Type u_1} [CommRing R] {ι : Type u_2}
  [Fintype ι] [DecidableEq ι] (H x : ι → R) (M : Matrix ι ι R) (hH : M.mulVec x = H) :
  have J := Ideal.span (Set.range H);
  LinearStudy.Annihilates (Ideal.span (Set.range fun i => (Ideal.Quotient.mk J) (x i))) ((Ideal.Quotient.mk J) M.det)

LinearStudy.annihilator_eq_scalar_generator.{u_1, u_2} {B : Type u_1} {A : Type u_2} [CommRing B] [CommRing A]
  [Algebra B A] (q : A →ₐ[B] B) (p : LinearStudy.PerfectMultiplicationPairing) {x : A}
  (hx : LinearStudy.Annihilates (RingHom.ker q.toRingHom) x) : x = p.functional x • LinearStudy.dualGenerator q p

LinearStudy.annihilates_nilradical_algEquiv.{u_1, u_2, u_3} (B : Type u_1) [CommRing B] {A : Type u_2} {C : Type u_3}
  [CommRing A] [CommRing C] [Algebra B A] [Algebra B C] (e : A ≃ₐ[B] C) (x : A) :
  LinearStudy.Annihilates (nilradical A) x ↔ LinearStudy.Annihilates (nilradical C) (e x)

LinearStudy.coordinate_annihilator_eq_coefficientDeterminant.{u_1} {R : Type u_1} [CommRing R] {k : ℕ}
  (H x : Fin (k + 1) → R) (hH : RingTheory.Sequence.IsRegular R (List.ofFn H))
  (hx : RingTheory.Sequence.IsRegular R (List.ofFn x)) (M : Matrix (Fin (k + 1)) (Fin (k + 1)) R) (h : M.mulVec x = H) :
  Submodule.annihilator (Ideal.map (Ideal.Quotient.mk (Ideal.span (Set.range H))) (Ideal.span (Set.range x))) =
    Ideal.span {(Ideal.Quotient.mk (Ideal.span (Set.range H))) M.det}

LinearStudy.linearEquationSubspace.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) :
  Projectivization.Subspace ℂ (LinearStudy.CoordinateVector n)

LinearStudy.mem_linearEquationSubmodule.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) (v : LinearStudy.CoordinateVector n) :
  v ∈ LinearStudy.linearEquationSubmodule equations ↔ ∀ (i : ι), (equations i) v = 0

LinearStudy.mem_linearEquationSubspace.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) (v : LinearStudy.CoordinateVector n) (hv : v ≠ 0) :
  Projectivization.mk ℂ v hv ∈ LinearStudy.linearEquationSubspace equations ↔ ∀ (i : ι), (equations i) v = 0

LinearStudy.nilpotentPowerSeriesEval_C.{u_1, u_2} {R : Type u_1} {S : Type u_2} [CommRing R] [CommRing S] {n : ℕ}
  (f : R →+* S) (a : Fin n → S) (ha : ∀ (i : Fin n), IsNilpotent (a i)) (b : R) :
  (LinearStudy.nilpotentPowerSeriesEval f a ha) (MvPowerSeries.C b) = f b

LinearStudy.nilpotentPowerSeriesEval_X.{u_1, u_2} {R : Type u_1} {S : Type u_2} [CommRing R] [CommRing S] {n : ℕ}
  (f : R →+* S) (a : Fin n → S) (ha : ∀ (i : Fin n), IsNilpotent (a i)) (i : Fin n) :
  (LinearStudy.nilpotentPowerSeriesEval f a ha) (MvPowerSeries.X i) = a i

LinearStudy.oneVariable_closedFiber_jacobian.{u_1} {K : Type u_1} [Field K] [CharZero K] (H : PowerSeries K)
  (hH : H ≠ 0) (h0 : PowerSeries.constantCoeff H = 0) :
  have I := Ideal.span {H};
  let A := PowerSeries K ⧸ I;
  have delta := (Ideal.Quotient.mk I) (PowerSeries.derivative H);
  IsArtinianRing A ∧ (nilradical A).IsMaximal ∧ Submodule.annihilator (nilradical A) = Ideal.span {delta} ∧ delta ≠ 0

LinearStudy.powerSeries_zeroConstant_variable_expansion.{u_1, u_2} {R : Type u_1} [CommRing R] {ι : Type u_2}
  [Fintype ι] [DecidableEq ι] [Nonempty ι] (H : MvPowerSeries ι R) (hH : MvPowerSeries.constantCoeff H = 0) :
  ∃ a, H = ∑ i, a i * MvPowerSeries.X i

LinearStudy.powerSeries_coefficientDeterminant_maximal_annihilator.{u_2, u_3} {ι : Type u_2} [Fintype ι] [DecidableEq ι]
  [Nonempty ι] {K : Type u_3} [Field K] (H : ι → MvPowerSeries ι K)
  (hH : ∀ (i : ι), MvPowerSeries.constantCoeff (H i) = 0) :
  have J := Ideal.span (Set.range H);
  have m := Ideal.span (Set.range fun i => (Ideal.Quotient.mk J) (MvPowerSeries.X i));
  m.IsMaximal ∧ ∃ M, M.mulVec MvPowerSeries.X = H ∧ (Ideal.Quotient.mk J) M.det ∈ Submodule.annihilator m

LinearStudy.homogeneous_ideal_vanish_unit_smul_iff {n : ℕ}
  (I : HomogeneousIdeal (MvPolynomial.homogeneousSubmodule (Fin (n + 1)) ℂ)) (v : LinearStudy.CoordinateVector n)
  (a : ℂˣ) : (∀ P ∈ I.toIdeal, (MvPolynomial.eval (a • v)) P = 0) ↔ ∀ P ∈ I.toIdeal, (MvPolynomial.eval v) P = 0

def LinearStudy.LinearityTheoremGoal : Prop :=
∀ (n : ℕ) (f : LinearStudy.HomogeneousEndomorphism n) (V : LinearStudy.IntegralProjectiveEquations n),
  1 < f.degree → Function.Surjective f.onPoints → f.onPoints ⁻¹' V.zeroSet = V.zeroSet → ∃ W, ↑W = V.zeroSet

LinearStudy.multiplication_factors_through_reduction.{u_1, u_2} {B : Type u_1} {A : Type u_2} [CommRing B] [CommRing A]
  [Algebra B A] (q : A →ₐ[B] B) (hq : ∀ (a : A), q a = 0 ↔ a ∈ nilradical A) {x : A}
  (hx : LinearStudy.Annihilates (nilradical A) x) (a : A) : a * x = (algebraMap B A) (q a) * x

LinearStudy.thickeningJacobian_annihilator.{u_1} (B : Type u_1) [CommRing B] (s : ℕ) [IsReduced B]
  (hunit : IsUnit ↑(s + 1)) :
  Submodule.annihilator (nilradical (LinearStudy.Thickening B s)) = Ideal.span {LinearStudy.thickeningJacobian B s}

